sql.where:
DELETED = 0

    AND ENTERPRISE_ID = #{enterpriseId}


    AND ENTERPRISE_NAME LIKE CONCAT('%', #{enterpriseName}, '%')


    AND INCIDENT_TYPE = #{incidentType}


    AND INCIDENT_CATEGORY = #{incidentCategory}


    AND SEVERITY_LEVEL = #{severityLevel}


    AND RISK_LEVEL = #{riskLevel}


    AND PROCESSING_STATUS = #{processingStatus}


    AND EMERGENCY_RESPONSE_LEVEL = #{emergencyResponseLevel}


    AND INCIDENT_TITLE LIKE CONCAT('%', #{incidentTitle}, '%')


    AND INCIDENT_NUMBER LIKE CONCAT('%', #{incidentNumber}, '%')


    AND OCCURRENCE_TIME >= #{startDate}


    AND OCCURRENCE_TIME <= #{endDate}


    AND ACTUAL_LOSS >= #{minLoss}


    AND ACTUAL_LOSS <= #{maxLoss}

mapper.select:
SELECT COUNT(*) as totalIncidents, COUNT(CASE WHEN PROCESSING_STATUS = 'REPORTED' THEN 1 END) as reportedCount, COUNT(CASE WHEN PROCESSING_STATUS = 'IN_PROGRESS' THEN 1 END) as inProgressCount, COUNT(CASE WHEN PROCESSING_STATUS = 'RESOLVED' THEN 1 END) as resolvedCount, COUNT(CASE WHEN PROCESSING_STATUS = 'CLOSED' THEN 1 END) as closedCount, COUNT(CASE WHEN SEVERITY_LEVEL = 'CRITICAL' THEN 1 END) as criticalCount, COUNT(CASE WHEN SEVERITY_LEVEL = 'HIGH' THEN 1 END) as highSeverityCount, COUNT(CASE WHEN EMERGENCY_RESPONSE_LEVEL IS NOT NULL THEN 1 END) as emergencyResponseCount, ROUND(AVG(RISK_SCORE), 2) as avgRiskScore, SUM(ACTUAL_LOSS) as totalActualLoss, SUM(DIRECT_LOSS) as totalDirectLoss, SUM(INDIRECT_LOSS) as totalIndirectLoss FROM TBL_RISK_INCIDENT WHERE DELETED = 0
AND ENTERPRISE_ID = #{enterpriseId}
AND OCCURRENCE_TIME >= #{startDate}
AND OCCURRENCE_TIME <= #{endDate}

SELECT INCIDENT_TYPE as incidentType, INCIDENT_CATEGORY as incidentCategory, COUNT(*) as count, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM TBL_RISK_INCIDENT WHERE DELETED = 0), 2) as percentage, SUM(ACTUAL_LOSS) as totalLoss, ROUND(AVG(RISK_SCORE), 2) as avgRiskScore FROM TBL_RISK_INCIDENT WHERE DELETED = 0
AND ENTERPRISE_ID = #{enterpriseId}
AND OCCURRENCE_TIME >= #{startDate}
AND OCCURRENCE_TIME <= #{endDate}
GROUP BY INCIDENT_TYPE, INCIDENT_CATEGORY ORDER BY count DESC
